const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);
const RETRYABLE_METHODS = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

function hasIdempotencyKey(headers) {
  if (headers == null) {
    return false;
  }

  if (typeof headers.get === "function") {
    return headers.get("Idempotency-Key") != null;
  }

  return Object.keys(headers).some(
    (name) => name.toLowerCase() === "idempotency-key"
  );
}

function isRetryableMethod(options) {
  const methodValue = options.method === undefined ? "GET" : options.method;
  const method = String(methodValue).toUpperCase();

  if (RETRYABLE_METHODS.has(method)) {
    return true;
  }

  return (
    (method === "POST" || method === "PATCH") &&
    hasIdempotencyKey(options.headers)
  );
}

function throwIfAborted(signal) {
  if (signal != null && signal.aborted) {
    const error = new Error("The operation was aborted");
    error.name = "AbortError";
    throw error;
  }
}

export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  return async function rfetch(url, options = {}) {
    let attempt = 1;
    let retryableMethod;

    while (true) {
      throwIfAborted(options.signal);

      if (attempt === 1) {
        retryableMethod = isRetryableMethod(options);
      }

      let response;

      try {
        response = await fetch(url, options);
      } catch (error) {
        if (error != null && error.name === "AbortError") {
          throw error;
        }

        if (!retryableMethod || attempt >= maxAttempts) {
          throw error;
        }

        const delayMs = Math.floor(
          random() *
            Math.min(
              maxDelayMs,
              baseDelayMs * 2 ** (attempt - 1)
            )
        );

        await sleep(delayMs, options.signal);
        attempt += 1;
        continue;
      }

      if (response.ok === true) {
        return response;
      }

      if (!RETRYABLE_STATUSES.has(response.status)) {
        return response;
      }

      if (!retryableMethod || attempt >= maxAttempts) {
        return response;
      }

      const retryAfter = response.headers.get("Retry-After");
      let delayMs;

      if (
        typeof retryAfter === "string" &&
        /^[0-9]+$/.test(retryAfter)
      ) {
        delayMs = Number(retryAfter) * 1000;

        if (delayMs > maxDelayMs) {
          return response;
        }
      } else {
        delayMs = Math.floor(
          random() *
            Math.min(
              maxDelayMs,
              baseDelayMs * 2 ** (attempt - 1)
            )
        );
      }

      await sleep(delayMs, options.signal);
      attempt += 1;
    }
  };
}
